import java.util.Objects;

final class Money {
    private final double amount;
    private final String currency;

    public Money(double amount, String currency) {
        this.amount = amount;
        this.currency = Objects.requireNonNull(currency, "currency cannot be null");
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Money other = (Money) obj;
        return Double.compare(this.amount, other.amount) == 0 &&
               Objects.equals(this.currency, other.currency);
    }

    @Override
    public int hashCode() {
        return Objects.hash(amount, currency);
    }

    @Override
    public String toString() {
        return String.format("%.2f %s", amount, currency);
    }
}

class Product {
    private final String sku;
    private String title;
    private Money price;

    public Product(String sku, String title, Money price) {
        this.sku = Objects.requireNonNull(sku, "sku cannot be null");
        this.title = title;
        this.price = price;
    }

    // Business key equality: Product equality is governed strictly by unique SKU
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Product other = (Product) obj;
        return Objects.equals(this.sku, other.sku);
    }

    @Override
    public int hashCode() {
        return Objects.hash(sku);
    }

    @Override
    public String toString() {
        return "Product[sku='" + sku + "', title='" + title + "', price=" + price + "]";
    }
}

public class ProductDemo {
    public static void main(String[] args) {
        Product p1 = new Product("SKU-4K-MONITOR", "UltraSharp 27", new Money(399.99, "USD"));
        Product p2 = new Product("SKU-4K-MONITOR", "UltraSharp 27 (Promo)", new Money(349.99, "USD"));

        System.out.println(p1);
        System.out.println("Products equal by SKU: " + p1.equals(p2));
        System.out.println("Hashes match: " + (p1.hashCode() == p2.hashCode()));
    }
}

