import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

class Customer {
    private final String customerId;
    private String fullName;
    private String email;
    private String taxId; // PII: must be masked in toString!

    public Customer(String id, String name, String email, String taxId) {
        this.customerId = Objects.requireNonNull(id, "customerId cannot be null");
        this.fullName = name;
        this.email = email;
        this.taxId = taxId;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Customer other = (Customer) obj;
        return Objects.equals(this.customerId, other.customerId);
    }

    @Override
    public int hashCode() {
        return Objects.hash(customerId);
    }

    private String maskTaxId(String raw) {
        if (raw == null || raw.length() < 4) return "***-**-****";
        return "***-**-" + raw.substring(raw.length() - 4);
    }

    @Override
    public String toString() {
        return "Customer[id='" + customerId + "', name='" + fullName + "', email='" + email + "', taxId='" + maskTaxId(taxId) + "']";
    }
}

public class CustomerRegistryDemo {
    public static void main(String[] args) {
        Set<Customer> registry = new HashSet<>();
        Customer c1 = new Customer("CUST-001", "Katherine Johnson", "kj@nasa.gov", "123-45-6789");
        Customer c2 = new Customer("CUST-001", "Katherine G. Johnson", "kjohnson@nasa.gov", "123-45-6789");

        registry.add(c1);
        boolean addedDup = registry.add(c2); // Rejected as duplicate!

        System.out.println("Duplicate added: " + addedDup); // false
        System.out.println("Registry size: " + registry.size()); // 1
        System.out.println(c1);
    }
}

