class InventoryStock {
    private Map<Product, Integer> stockMap = new HashMap<>();
    public void restock(Product p, int qty) {
        stockMap.put(p, stockMap.getOrDefault(p, 0) + qty);
    }
    public int getQuantity(Product p) {
        return stockMap.getOrDefault(p, 0);
    }
}

public class InventoryApp {
    public static void main(String[] args) {
        InventoryStock stock = new InventoryStock();
        Product p1 = new Product("SKU-100", "Gaming Mouse");
        Product p2 = new Product("SKU-100", "Gaming Mouse (V2)");

        stock.restock(p1, 10);
        stock.restock(p2, 5);

        System.out.println("Total stock for SKU-100: " + stock.getQuantity(p1));
    }
}

