    private Map<Product, Integer> stock = new HashMap<>();

    public boolean addCustomer(Customer c) {
        return customers.add(c);
    }
    public void addStock(Product p, int qty) {
        stock.put(p, stock.getOrDefault(p, 0) + qty);
    }
    public void printStoreReport() {
        System.out.println("=== Store Directory ===");
        System.out.println("Customers: " + customers.size());
        System.out.println("Products in catalog: " + stock.size());
        for (Map.Entry<Product, Integer> entry : stock.entrySet()) {
            System.out.println(" - " + entry.getKey() + " | In Stock: " + entry.getValue());
        }
    }
}

public class StoreApp {
