        Customer c1 = new Customer("C-1", "Alice", "111-22-3333");
        Customer c2 = new Customer("C-1", "Alice Duplicate", "111-22-3333");

        StoreRegistry store = new StoreRegistry();
        store.addCustomer(c1);
        store.addCustomer(c2); // Rejected duplicate
        store.addStock(p1, 20);

        store.printStoreReport();
    }
}
